const artAssets={"clay": "data:image/jpeg;base64,", "portal": "data:image/jpeg;base64,"};
(()=>{
const root=document.getElementById('campus-signature-pair');
const configs=[
['observatory','Midnight Observatory — Signature','YOUR FUTURE IS STILL WIDE OPEN','Find your direction.<br>Build your future.','Explore tech roles, learn with a clear plan, and turn your ideas into work you can show.','Find your direction','Step into<br>your next chapter.','A clear path for your learning, ideas, and growth.','portal']
];
const blocks=['College Courses','Social & Confidence','Entrepreneurship','Student Money','Service Studio'];
const details=['Choose your tech degree, follow a roadmap, find subject playlists, explore roles, and build a private work portfolio.','Search student concerns and find selected videos by problem and language.','Check costs and find potential teammates through the WhatsApp group.','Track expenses, plan savings, and split bills.','Describe a problem and request free personal help, with files and replies.'];
const blockButtons=()=>blocks.map((b,i)=>`<button type="button" data-block="${i}">${b} ↗</button>`).join('');
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let choice=window.openai?.widgetState?.modelContent?.campusSignatureChoice||'';
function showChoice(){root.querySelectorAll('[data-select]').forEach(b=>{const yes=b.closest('.world').dataset.name===choice;b.textContent=yes?'Selected ✓':'Choose this design';b.setAttribute('aria-pressed',String(yes));});}
root.querySelectorAll('.world').forEach((site,i)=>{
const [type,name,tag,heading,intro,cta,loginHeading,loginIntro,art]=configs[i],prefix='cw-eight-'+i;
site.dataset.name=name;site.dataset.type=type;site.dataset.motion=reduced()?'off':'on';site.dataset.authmode='login';
site.innerHTML=`<header class="topbar"><button type="button" class="brand" data-top><b>c.</b><span class="brand-text kinetic">Collexion Campus</span></button><nav class="nav" aria-label="Welcome navigation"><button type="button" class="text-button" data-overview>Explore the campus</button><button type="button" class="action" data-login>Log in ↗</button></nav></header><section class="hero"><div class="scene-decoration kinetic" aria-hidden="true"></div><div class="hero-copy"><p class="eyebrow">${tag}</p><h1 aria-label="Collexion Campus"><span class="brand-line kinetic">Collexion</span><span class="brand-line kinetic">Campus</span></h1><h2 class="hero-subtitle">${heading}</h2><p class="intro">${intro}</p><button type="button" class="action primary" data-start>${cta} ↗</button></div><div class="stage" role="group" aria-label="${name} interactive 3D scene"><img class="fallback kinetic" src="${artAssets[art]}" alt="Student artwork shown while the 3D scene loads" width="850" height="567"></div><div class="caption"><span>Explore your campus in 3D. Drag to rotate, or use the arrow buttons.</span><div class="lens-controls"><button type="button" data-camera="left" aria-label="Rotate scene left">↶</button><button type="button" data-camera="right" aria-label="Rotate scene right">↷</button><button type="button" data-camera="reset">Reset view</button></div></div></section><div class="welcome-strip"><span>YOUR WELCOME IS ONLY THE BEGINNING</span><button type="button" data-login>Continue to login ↓</button></div><section class="overview" hidden><h2>Your five campus spaces</h2><div class="blocks">${blockButtons()}</div><p class="detail" aria-live="polite">Choose a block to see what it does.</p><button type="button" class="text-button" data-close-overview>Close overview ↑</button></section><section class="login" id="${prefix}-login"><div class="login-copy"><p class="eyebrow">${name}</p><h2>${loginHeading}</h2><p>${loginIntro}</p><p>Your portfolio stays private until you choose to share it.</p></div><div class="login-world" aria-hidden="true"><img class="fallback kinetic" src="${artAssets[art]}" alt="" width="850" height="567"></div><div class="login-frame"><div class="login-card"><div class="auth-tabs"><button type="button" data-mode="login" aria-pressed="true">Log in</button><button type="button" data-mode="signup" aria-pressed="false">Create account</button></div><form><label class="field name-field" for="${prefix}-name" hidden>Your name<input id="${prefix}-name" name="displayName" maxlength="80" autocomplete="on" placeholder="Your name"></label><label class="field" for="${prefix}-email">Email<input id="${prefix}-email" name="email" type="email" required autocomplete="on" placeholder="student@example.com"></label><label class="field password-field" for="${prefix}-password">Password<span class="password"><input id="${prefix}-password" name="password" type="password" required minlength="10" autocomplete="on" placeholder="At least 10 characters"><button type="button" data-show aria-pressed="false" aria-label="Show password">Show</button></span></label><label class="live-auth-extra recovery-field" hidden>Recovery code<input name="recoveryCode" autocomplete="off" maxlength="100"></label><label class="live-auth-extra owner-field" hidden>Private owner setup code<input name="adminCode" type="password" autocomplete="off"></label><label class="live-auth-extra live-privacy-check privacy-field" hidden><input name="consent" type="checkbox"><span>I agree to store my account and the information I submit. Help requests and attachments are visible to the campus admin. My money records and private portfolio are not.</span></label><button type="button" class="text-button forgot" data-mode="reset">Forgot password?</button><button type="submit" class="action primary submit">Log in →</button><p class="message" role="status"></p></form><section class="signed-in" hidden><h3>Welcome to your campus</h3><div class="blocks">${blockButtons()}</div><p class="detail" aria-live="polite">Choose a space to see what comes next.</p><button type="button" class="action" data-signout>Back to login</button></section><p class="preview-note">Your data is saved to your account. Keep your recovery code safe; password recovery uses that code, not email.</p></div></div></section><footer><div class="footer-copy"><strong>${name}</strong><span class="engine-status" role="status">Preparing the 3D scene</span></div><div class="footer-actions"><button type="button" class="motion-setting" data-motion aria-pressed="${!reduced()}" ${reduced()?'disabled':''}>${reduced()?'Reduced motion':'Pause animation'}</button></div></footer>`;
site.querySelectorAll('button').forEach(b=>b.classList.add('cursor-interaction'));
const q=s=>site.querySelector(s),form=q('form'),fields=form.elements,card=q('.login-card');let mode='login';
function animateCard(kind='enter'){if(reduced()||site.dataset.motion==='off')return;const poses={enter:[{transform:'translateY(65px) rotateY(-24deg) scale(.9)'},{transform:'translateY(0) rotateY(0) scale(1)'}],signup:[{transform:'rotateY(-18deg) translateZ(-30px)'},{transform:'rotateY(0) translateZ(0)'}],login:[{transform:'rotateY(15deg)'},{transform:'rotateY(0)'}],reset:[{transform:'rotateX(-14deg)'},{transform:'rotateX(0)'}],success:[{transform:'translateZ(0) scale(1)'},{transform:'translateZ(65px) scale(1.04)'},{transform:'translateZ(0) scale(1)'}]};card.animate?.(poses[kind]||poses.enter,{duration:850,easing:'cubic-bezier(.16,.8,.2,1)'});}
function move(el){el.scrollIntoView({behavior:reduced()?'auto':'smooth',block:'start'});if(el===q('.login')){site.dataset.focus='login';animateCard();}}
function setMode(next){mode=next;site.dataset.authmode=next;form.hidden=false;q('.signed-in').hidden=true;q('.auth-tabs').hidden=false;q('.name-field').hidden=next!=='signup';fields.displayName.required=next==='signup';q('.password-field').hidden=false;fields.password.required=true;fields.password.disabled=false;q('.recovery-field').hidden=next!=='reset';fields.recoveryCode.required=next==='reset';q('.privacy-field').hidden=next!=='signup';fields.consent.required=next==='signup';q('.owner-field').hidden=!(next==='signup'&&fields.email.value.toLowerCase()==='aryamangupta55@gmail.com'&&!Campus.adminVerified);q('.forgot').hidden=next==='reset';q('.submit').textContent=next==='signup'?'Create account →':next==='reset'?'Reset with recovery code →':'Log in →';q('.message').textContent='';q('.preview-note').textContent='Your data is saved to your account. Keep your recovery code safe; password recovery uses that code, not email.';q('.auth-tabs').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===next)));animateCard(next);}
site.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!site.contains(b))return;
if(b.hasAttribute('data-login')){setMode('login');move(q('.login'));}if(b.hasAttribute('data-start')){setMode('signup');move(q('.login'));}if(b.hasAttribute('data-top')){site.dataset.focus='welcome';move(site);}if(b.hasAttribute('data-overview')){q('.overview').hidden=false;move(q('.overview'));}if(b.hasAttribute('data-close-overview')){q('.overview').hidden=true;move(q('.hero'));}
if(b.dataset.mode)setMode(b.dataset.mode);
if(b.hasAttribute('data-show')){const show=fields.password.type==='password';fields.password.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password');b.setAttribute('aria-pressed',String(show));}
if(b.dataset.block!==undefined){const inDashboard=b.closest('.signed-in');if(inDashboard){inDashboard.querySelector('.detail').textContent=details[Number(b.dataset.block)];}else{q('.overview').hidden=false;q('.overview .detail').textContent=details[Number(b.dataset.block)];move(q('.overview'));}}
if(b.hasAttribute('data-motion')){const paused=site.dataset.motion==='on';site.dataset.motion=paused?'off':'on';b.textContent=paused?'Play motion':'Pause animation';b.setAttribute('aria-pressed',String(!paused));if(paused){card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg');}}
if(b.hasAttribute('data-replay')){if(!reduced()){site.dataset.motion='on';q('[data-motion]').textContent='Pause animation';q('[data-motion]').setAttribute('aria-pressed','true');site.dataset.replay=String(Date.now());q('.hero-copy').animate?.([{transform:'translateY(45px)'},{transform:'translateY(0)'}],{duration:900,easing:'cubic-bezier(.16,.8,.2,1)'});animateCard();}}
if(b.hasAttribute('data-signout')){form.reset();setMode('login');}
if(b.hasAttribute('data-select')){choice=name;showChoice();window.openai?.setWidgetState?.({modelContent:{campusSignatureChoice:choice},privateContent:null})?.catch(()=>{});}
});
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const submit=q('.submit');submit.disabled=true;q('.message').textContent='Connecting securely…';try{const result=await Campus.api('/auth/'+(mode==='reset'?'recover':mode),'POST',{email:fields.email.value,password:fields.password.value,name:fields.displayName.value,recoveryCode:fields.recoveryCode.value,adminCode:fields.adminCode.value});form.reset();await Campus.signedIn(result);}catch(error){q('.message').textContent=error.message;}finally{submit.disabled=false;}});
fields.email.addEventListener('input',()=>{q('.owner-field').hidden=!(mode==='signup'&&fields.email.value.toLowerCase()==='aryamangupta55@gmail.com'&&!Campus.adminVerified);});
q('.preview-note').insertAdjacentHTML('afterend','<details class="live-privacy"><summary>Privacy & account help</summary><p>We store your name, email, successful login count, selected course, progress, portfolio, and money records. Only you can access your private portfolio and money records. The admin can access account details and your help requests. Do not upload passwords, bank details, or identity documents. For corrections or deletion, contact aryamangupta55@gmail.com. Email addresses are not verified for student signup.</p></details><div class="live-admin-access"><p>Owner signup: enter the private admin setup code you saved in Cloudflare.</p></div>');
if(new URLSearchParams(location.search).has('owner')){setMode('signup');fields.email.value='aryamangupta55@gmail.com';q('.owner-field').hidden=!!Campus.adminVerified;move(q('.login'));}
card.addEventListener('pointermove',e=>{if(reduced()||site.dataset.motion==='off'||e.pointerType==='touch')return;const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',Math.max(-5,Math.min(5,(r.top+r.height/2-e.clientY)/45))+'deg');card.style.setProperty('--tilt-y',Math.max(-6,Math.min(6,(e.clientX-r.left-r.width/2)/35))+'deg');});card.addEventListener('pointerleave',()=>{card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg');});form.addEventListener('focusin',e=>site.dataset.field=e.target.name||'');form.addEventListener('focusout',()=>site.dataset.field='');
if(globalThis.IntersectionObserver)new IntersectionObserver(entries=>{if(entries[0].isIntersecting)site.dataset.focus='login';else site.dataset.focus='welcome';},{threshold:.2}).observe(q('.login'));
});
showChoice();
})();
